LANGS = ['en', 'de', 'fr', 'es', 'it', 'nl']
for i, lang in enumerate(LANGS):
    root = {}
    for key, vals in K.items():
        assert len(vals) == 6, key
        node = root.setdefault('jolly', {})
        parts = key.split('.')
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = vals[i]
    (OUT / f'{lang}.json').write_text(json.dumps(root, indent=2, ensure_ascii=False) + '\n')
print(len(K), 'keys x', len(LANGS))
